from __future__ import annotations

import re
from pathlib import Path

ROOT = Path.cwd()


def write(path: str, text: str) -> None:
    p = ROOT / path
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(text.strip() + "\n", encoding="utf-8")


CLI_BLOCK = '\n# BEGIN SLICE18C HSIC REPORT EXPORT CLI\n@pirs_app.command("export-hsic-report")\ndef pirs_export_hsic_report(\n    run_dir: Path = typer.Option(..., "--run-dir", exists=True, file_okay=False, dir_okay=True),\n    ranking_manifest: Path | None = typer.Option(None, "--ranking-manifest", exists=False, file_okay=True, dir_okay=False),\n    output_dir: Path | None = typer.Option(None, "--output-dir", exists=False, file_okay=False, dir_okay=True),\n) -> None:\n    """Export a read-only HSIC evidence report bundle from ranked scan artifacts."""\n    from pegasus.workflows.hsic_report import run_export_hsic_report\n\n    payload = run_export_hsic_report(\n        run_dir=run_dir,\n        ranking_manifest=ranking_manifest,\n        output_dir=output_dir,\n    )\n    typer.echo(json.dumps(payload, ensure_ascii=False, sort_keys=True, indent=2, default=str))\n\n\n@pirs_app.command("inspect-hsic-report")\ndef pirs_inspect_hsic_report(\n    manifest: Path = typer.Option(..., "--manifest", exists=True, file_okay=True, dir_okay=False),\n) -> None:\n    """Inspect an exported HSIC evidence report manifest without mutating a run."""\n    from pegasus.workflows.hsic_report import inspect_hsic_report_manifest\n\n    payload = inspect_hsic_report_manifest(manifest)\n    typer.echo(json.dumps(payload, ensure_ascii=False, sort_keys=True, indent=2, default=str))\n# END SLICE18C HSIC REPORT EXPORT CLI\n'
HSIC_REPORT = '\nfrom __future__ import annotations\n\nimport csv\nimport json\nfrom dataclasses import dataclass\nfrom datetime import datetime, timezone\nfrom pathlib import Path\nfrom typing import Any, Iterable\n\nimport pyarrow.parquet as pq\n\nRUN_SUMMARY_FILES = (\n    "RunConfig.json",\n    "P_vector.json",\n    "UserIntent.json",\n    "ReproducibilityManifest.json",\n)\n\nREPORT_MARKER = "<!-- PegaSUS HSIC evidence report: read-only generated artifact -->"\n\n\n@dataclass(frozen=True)\nclass HSICEvidenceItem:\n    rank: int\n    hypothesis_id: str\n    residual_field_id: str | None\n    covariate_field_id: str | None\n    statistic: float | None\n    p_value: float | None\n    q_value: float | None\n    n_eff: float | None\n    state: str\n    evidence_tier: str\n    decision: str\n    warnings: list[str]\n    hsic_mode: str | None = None\n    residual_mode: str | None = None\n    fold_scheme: str | None = None\n\n    def as_json(self) -> dict[str, Any]:\n        return {\n            "rank": self.rank,\n            "hypothesis_id": self.hypothesis_id,\n            "residual_field_id": self.residual_field_id,\n            "covariate_field_id": self.covariate_field_id,\n            "statistic": self.statistic,\n            "p_value": self.p_value,\n            "q_value": self.q_value,\n            "n_eff": self.n_eff,\n            "state": self.state,\n            "evidence_tier": self.evidence_tier,\n            "decision": self.decision,\n            "warnings": list(self.warnings),\n            "hsic_mode": self.hsic_mode,\n            "residual_mode": self.residual_mode,\n            "fold_scheme": self.fold_scheme,\n            "dashboard_safe": True,\n            "read_only": True,\n        }\n\n    def as_csv(self) -> dict[str, Any]:\n        payload = self.as_json()\n        payload["warnings"] = ";".join(self.warnings)\n        return payload\n\n\ndef _read_json(path: Path) -> dict[str, Any]:\n    return json.loads(path.read_text(encoding="utf-8"))\n\n\ndef _write_json(path: Path, payload: dict[str, Any]) -> None:\n    path.parent.mkdir(parents=True, exist_ok=True)\n    path.write_text(json.dumps(payload, ensure_ascii=False, sort_keys=True, indent=2, default=str) + "\\n", encoding="utf-8")\n\n\ndef _read_parquet_rows(path: Path) -> list[dict[str, Any]]:\n    if not path.exists():\n        return []\n    return pq.read_table(path).to_pylist()\n\n\ndef _warnings(value: Any) -> list[str]:\n    if value is None:\n        return []\n    if isinstance(value, list):\n        return [str(v) for v in value]\n    if isinstance(value, str):\n        value = value.strip()\n        if not value:\n            return []\n        try:\n            parsed = json.loads(value)\n        except json.JSONDecodeError:\n            return [value]\n        if isinstance(parsed, list):\n            return [str(v) for v in parsed]\n        return [str(parsed)]\n    return [str(value)]\n\n\ndef _number(value: Any) -> float | None:\n    if value is None:\n        return None\n    try:\n        return float(value)\n    except (TypeError, ValueError):\n        return None\n\n\ndef _cards_from_dashboard(path: Path) -> list[dict[str, Any]]:\n    if not path.exists():\n        return []\n    payload = _read_json(path)\n    cards = payload.get("cards")\n    if not isinstance(cards, list):\n        return []\n    return [dict(card) for card in cards if isinstance(card, dict) and card.get("dashboard_safe", True)]\n\n\ndef _cards_from_ranking_manifest(path: Path) -> list[dict[str, Any]]:\n    if not path.exists():\n        return []\n    payload = _read_json(path)\n    rows = payload.get("ranked_hypotheses")\n    if isinstance(rows, list):\n        return [dict(row) for row in rows if isinstance(row, dict) and row.get("dashboard_safe", True)]\n    return []\n\n\ndef _cards_from_ranking_parquet(path: Path) -> list[dict[str, Any]]:\n    rows = _read_parquet_rows(path)\n    return [dict(row) for row in rows if row.get("dashboard_safe", True)]\n\n\ndef _metrics_value(row: dict[str, Any], key: str) -> Any:\n    metrics = row.get("metrics")\n    if isinstance(metrics, dict) and key in metrics:\n        return metrics.get(key)\n    return row.get(key)\n\n\ndef _evidence_items(cards: Iterable[dict[str, Any]]) -> list[HSICEvidenceItem]:\n    items: list[HSICEvidenceItem] = []\n    for idx, row in enumerate(cards, start=1):\n        hypothesis_id = str(row.get("hypothesis_id") or f"hsic_report_item_{idx}")\n        warnings = _warnings(row.get("warnings"))\n        state = str(row.get("state") or "exploratory")\n        evidence_tier = str(row.get("evidence_tier") or "exploratory_descriptive")\n        decision = str(row.get("decision") or "show_as_exploratory")\n        items.append(HSICEvidenceItem(\n            rank=int(row.get("rank") or idx),\n            hypothesis_id=hypothesis_id,\n            residual_field_id=row.get("residual_field_id"),\n            covariate_field_id=row.get("covariate_field_id"),\n            statistic=_number(_metrics_value(row, "statistic")),\n            p_value=_number(_metrics_value(row, "p_value")),\n            q_value=_number(_metrics_value(row, "q_value")),\n            n_eff=_number(_metrics_value(row, "n_eff")),\n            state=state,\n            evidence_tier=evidence_tier,\n            decision=decision,\n            warnings=warnings,\n            hsic_mode=row.get("hsic_mode"),\n            residual_mode=row.get("residual_mode"),\n            fold_scheme=row.get("fold_scheme"),\n        ))\n    return sorted(items, key=lambda item: (item.rank, item.hypothesis_id))\n\n\ndef _fmt(value: Any) -> str:\n    if value is None:\n        return ""\n    if isinstance(value, float):\n        return f"{value:.6g}"\n    return str(value)\n\n\ndef render_hsic_markdown_report(items: list[HSICEvidenceItem], *, generated_at: str, source: str | None = None) -> str:\n    lines: list[str] = [\n        REPORT_MARKER,\n        "# PegaSUS HSIC residual evidence report",\n        "",\n        f"Generated at: {generated_at}",\n        "",\n        "This report is a read-only descriptive export. It does not refit PIRS models, rerun HSIC, or mutate the output bundle.",\n        "",\n    ]\n    if source:\n        lines += [f"Source ranking manifest: `{source}`", ""]\n    lines += [\n        f"Evidence items: {len(items)}",\n        "",\n        "| Rank | Hypothesis | Covariate | State | Evidence tier | q | p | statistic | n_eff | Decision |",\n        "|---:|---|---|---|---|---:|---:|---:|---:|---|",\n    ]\n    for item in items:\n        lines.append(\n            "| "\n            + " | ".join([\n                str(item.rank),\n                item.hypothesis_id,\n                item.covariate_field_id or "",\n                item.state,\n                item.evidence_tier,\n                _fmt(item.q_value),\n                _fmt(item.p_value),\n                _fmt(item.statistic),\n                _fmt(item.n_eff),\n                item.decision,\n            ])\n            + " |"\n        )\n    lines += ["", "## Warnings", ""]\n    if not items:\n        lines.append("No dashboard-safe HSIC evidence items were available.")\n    else:\n        for item in items:\n            if item.warnings:\n                lines.append(f"- {item.hypothesis_id}: {\', \'.join(item.warnings)}")\n        if not any(item.warnings for item in items):\n            lines.append("No warnings recorded for exported evidence items.")\n    return "\\n".join(lines) + "\\n"\n\n\ndef _write_csv(path: Path, items: list[HSICEvidenceItem]) -> None:\n    path.parent.mkdir(parents=True, exist_ok=True)\n    columns = [\n        "rank", "hypothesis_id", "residual_field_id", "covariate_field_id", "statistic", "p_value",\n        "q_value", "n_eff", "state", "evidence_tier", "decision", "warnings", "hsic_mode",\n        "residual_mode", "fold_scheme", "dashboard_safe", "read_only",\n    ]\n    with path.open("w", encoding="utf-8", newline="") as fh:\n        writer = csv.DictWriter(fh, fieldnames=columns)\n        writer.writeheader()\n        for item in items:\n            writer.writerow(item.as_csv())\n\n\ndef _attach_summary_to_run(run_dir: Path, key: str, summary: dict[str, Any]) -> None:\n    for name in RUN_SUMMARY_FILES:\n        path = run_dir / name\n        if not path.exists():\n            continue\n        try:\n            payload = _read_json(path)\n        except Exception:\n            continue\n        payload[key] = summary\n        _write_json(path, payload)\n\n\ndef build_hsic_report_artifacts(\n    *,\n    run_dir: str | Path,\n    ranking_manifest: str | Path | None = None,\n    output_dir: str | Path | None = None,\n) -> dict[str, Any]:\n    run_dir = Path(run_dir)\n    tables = run_dir / "Tables"\n    ranking_manifest_path = Path(ranking_manifest) if ranking_manifest is not None else tables / "hsic_residual_scan_ranking_manifest.json"\n    if not ranking_manifest_path.exists():\n        raise FileNotFoundError(f"HSIC ranking manifest not found: {ranking_manifest_path}")\n\n    out_dir = Path(output_dir) if output_dir is not None else tables\n    out_dir.mkdir(parents=True, exist_ok=True)\n\n    dashboard_path = tables / "dashboard_hsic_cards.json"\n    ranking_parquet_path = tables / "hsic_residual_scan_ranking.parquet"\n\n    cards = _cards_from_dashboard(dashboard_path)\n    source_kind = "dashboard_cards"\n    if not cards:\n        cards = _cards_from_ranking_manifest(ranking_manifest_path)\n        source_kind = "ranking_manifest"\n    if not cards:\n        cards = _cards_from_ranking_parquet(ranking_parquet_path)\n        source_kind = "ranking_parquet"\n\n    items = _evidence_items(cards)\n    generated_at = datetime.now(timezone.utc).isoformat()\n\n    report_json_path = out_dir / "hsic_evidence_report.json"\n    report_md_path = out_dir / "hsic_evidence_report.md"\n    report_csv_path = out_dir / "hsic_evidence_report.csv"\n    manifest_path = out_dir / "hsic_evidence_report_manifest.json"\n\n    report_payload = {\n        "schema_version": "1.0",\n        "slice": "18C",\n        "read_only": True,\n        "generated_at": generated_at,\n        "source_kind": source_kind,\n        "source_ranking_manifest": str(ranking_manifest_path),\n        "source_dashboard_cards": str(dashboard_path),\n        "evidence_count": len(items),\n        "items": [item.as_json() for item in items],\n    }\n    _write_json(report_json_path, report_payload)\n    report_md_path.write_text(\n        render_hsic_markdown_report(items, generated_at=generated_at, source=str(ranking_manifest_path)),\n        encoding="utf-8",\n    )\n    _write_csv(report_csv_path, items)\n\n    summary = {\n        "gate": "hsic_report_gate",\n        "schema_version": "1.0",\n        "slice": "18C",\n        "status": "exported" if items else "empty",\n        "read_only": True,\n        "evidence_count": len(items),\n        "source_kind": source_kind,\n        "top_hypothesis_id": items[0].hypothesis_id if items else None,\n        "manifest_path": str(manifest_path),\n        "report_json_path": str(report_json_path),\n        "report_md_path": str(report_md_path),\n        "report_csv_path": str(report_csv_path),\n    }\n    try:\n        from pegasus.output.validate import validate_output_bundle\n        validation = validate_output_bundle(run_dir=str(run_dir))\n        summary["output_validation"] = {"ok": bool(validation.ok), "errors": list(validation.errors)}\n    except Exception as exc:  # pragma: no cover\n        summary["output_validation"] = {"ok": False, "errors": [str(exc)]}\n\n    manifest = {\n        **summary,\n        "generated_at": generated_at,\n        "source_ranking_manifest": str(ranking_manifest_path),\n        "source_dashboard_cards": str(dashboard_path),\n        "items": [item.as_json() for item in items],\n    }\n    _write_json(manifest_path, manifest)\n    _attach_summary_to_run(run_dir, "hsic_report_gate", summary)\n    return manifest\n\n\ndef inspect_hsic_report_manifest(path: str | Path) -> dict[str, Any]:\n    payload = _read_json(Path(path))\n    return {\n        "schema_version": payload.get("schema_version"),\n        "slice": payload.get("slice"),\n        "status": payload.get("status"),\n        "read_only": payload.get("read_only"),\n        "evidence_count": payload.get("evidence_count"),\n        "top_hypothesis_id": payload.get("top_hypothesis_id"),\n        "report_json_path": payload.get("report_json_path"),\n        "report_md_path": payload.get("report_md_path"),\n        "report_csv_path": payload.get("report_csv_path"),\n    }\n\n\n__all__ = [\n    "HSICEvidenceItem",\n    "build_hsic_report_artifacts",\n    "inspect_hsic_report_manifest",\n    "render_hsic_markdown_report",\n]\n'
HSIC_REPORT_WORKFLOW = '\nfrom __future__ import annotations\n\nfrom pathlib import Path\nfrom typing import Any\n\nfrom pegasus.pirs.hsic_report import build_hsic_report_artifacts, inspect_hsic_report_manifest\n\n\ndef run_export_hsic_report(\n    *,\n    run_dir: str | Path,\n    ranking_manifest: str | Path | None = None,\n    output_dir: str | Path | None = None,\n) -> dict[str, Any]:\n    return build_hsic_report_artifacts(run_dir=run_dir, ranking_manifest=ranking_manifest, output_dir=output_dir)\n\n\ndef run_attach_hsic_report_to_run(\n    *,\n    run_dir: str | Path,\n    ranking_manifest: str | Path | None = None,\n    output_dir: str | Path | None = None,\n) -> dict[str, Any]:\n    return build_hsic_report_artifacts(run_dir=run_dir, ranking_manifest=ranking_manifest, output_dir=output_dir)\n\n\n__all__ = [\n    "run_export_hsic_report",\n    "run_attach_hsic_report_to_run",\n    "inspect_hsic_report_manifest",\n]\n'
UNIT_TEST = '\nfrom __future__ import annotations\n\nfrom pegasus.pirs.hsic_report import HSICEvidenceItem, render_hsic_markdown_report\n\n\ndef test_slice18c_markdown_report_is_read_only_and_contains_evidence_table() -> None:\n    item = HSICEvidenceItem(\n        rank=1,\n        hypothesis_id="h1",\n        residual_field_id="resid",\n        covariate_field_id="cov_a",\n        statistic=0.42,\n        p_value=0.01,\n        q_value=0.02,\n        n_eff=33.0,\n        state="exploratory",\n        evidence_tier="supported_descriptive",\n        decision="retain_for_review",\n        warnings=[],\n        hsic_mode="exact_linear",\n        residual_mode="in_sample",\n        fold_scheme="none",\n    )\n    text = render_hsic_markdown_report([item], generated_at="2026-06-13T00:00:00+00:00", source="manifest.json")\n    assert "read-only descriptive export" in text\n    assert "| Rank | Hypothesis | Covariate" in text\n    assert "h1" in text\n    assert "cov_a" in text\n    assert "retain_for_review" in text\n\n\ndef test_slice18c_evidence_item_serializes_dashboard_safe_read_only() -> None:\n    item = HSICEvidenceItem(\n        rank=2,\n        hypothesis_id="h2",\n        residual_field_id=None,\n        covariate_field_id="cov_b",\n        statistic=None,\n        p_value=None,\n        q_value=None,\n        n_eff=None,\n        state="fragile",\n        evidence_tier="fragile_descriptive",\n        decision="show_as_fragile",\n        warnings=["small_support"],\n    )\n    payload = item.as_json()\n    assert payload["dashboard_safe"] is True\n    assert payload["read_only"] is True\n    assert payload["warnings"] == ["small_support"]\n'
INTEGRATION_TEST = '\nfrom __future__ import annotations\n\nimport json\nfrom pathlib import Path\n\nfrom typer.testing import CliRunner\n\nfrom pegasus.cli import app\nfrom pegasus.output.bundle import create_empty_output_bundle\nfrom pegasus.output.validate import validate_output_bundle\nfrom pegasus.workflows.hsic_report import inspect_hsic_report_manifest, run_export_hsic_report\n\n\ndef _write_json(path: Path, payload: dict) -> None:\n    path.parent.mkdir(parents=True, exist_ok=True)\n    path.write_text(json.dumps(payload, ensure_ascii=False, sort_keys=True, indent=2), encoding="utf-8")\n\n\ndef _seed_ranked_hsic_run(run_dir: Path) -> None:\n    create_empty_output_bundle(run_dir)\n    tables = run_dir / "Tables"\n    cards = [\n        {\n            "rank": 1,\n            "hypothesis_id": "hsic__resid__cov_a",\n            "title": "HSIC residual signal: cov_a",\n            "residual_field_id": "resid",\n            "covariate_field_id": "cov_a",\n            "metrics": {"statistic": 0.9, "p_value": 0.01, "q_value": 0.04, "n_eff": 40.0},\n            "state": "exploratory",\n            "evidence_tier": "supported_descriptive",\n            "decision": "retain_for_review",\n            "warnings": [],\n            "dashboard_safe": True,\n            "read_only": True,\n        },\n        {\n            "rank": 2,\n            "hypothesis_id": "hsic__resid__cov_b",\n            "title": "HSIC residual signal: cov_b",\n            "residual_field_id": "resid",\n            "covariate_field_id": "cov_b",\n            "metrics": {"statistic": 0.2, "p_value": 0.5, "q_value": 0.8, "n_eff": 8.0},\n            "state": "fragile",\n            "evidence_tier": "fragile_descriptive",\n            "decision": "show_as_fragile",\n            "warnings": ["hsic_descriptive_small_support"],\n            "dashboard_safe": True,\n            "read_only": True,\n        },\n    ]\n    _write_json(tables / "dashboard_hsic_cards.json", {\n        "schema_version": "1.0",\n        "slice": "18B",\n        "read_only": True,\n        "card_count": len(cards),\n        "cards": cards,\n    })\n    _write_json(tables / "hsic_residual_scan_ranking_manifest.json", {\n        "schema_version": "1.0",\n        "slice": "18B",\n        "status": "ranked",\n        "rank_count": len(cards),\n        "dashboard_card_count": len(cards),\n        "ranked_hypotheses": cards,\n    })\n\n\ndef test_slice18c_exports_hsic_report_without_mutating_output_bundle(tmp_path: Path) -> None:\n    run_dir = tmp_path / "run"\n    _seed_ranked_hsic_run(run_dir)\n    payload = run_export_hsic_report(run_dir=run_dir)\n    assert payload["status"] == "exported"\n    assert payload["evidence_count"] == 2\n    assert (run_dir / "Tables" / "hsic_evidence_report.json").exists()\n    assert (run_dir / "Tables" / "hsic_evidence_report.md").exists()\n    assert (run_dir / "Tables" / "hsic_evidence_report.csv").exists()\n    assert (run_dir / "Tables" / "hsic_evidence_report_manifest.json").exists()\n    text = (run_dir / "Tables" / "hsic_evidence_report.md").read_text(encoding="utf-8")\n    assert "PegaSUS HSIC residual evidence report" in text\n    assert "cov_a" in text\n    validation = validate_output_bundle(run_dir=str(run_dir))\n    assert validation.ok, validation.errors\n    run_config = json.loads((run_dir / "RunConfig.json").read_text(encoding="utf-8"))\n    assert run_config["hsic_report_gate"]["status"] == "exported"\n    inspect = inspect_hsic_report_manifest(run_dir / "Tables" / "hsic_evidence_report_manifest.json")\n    assert inspect["read_only"] is True\n    assert inspect["evidence_count"] == 2\n\n\ndef test_slice18c_cli_exports_and_inspects_hsic_report(tmp_path: Path) -> None:\n    run_dir = tmp_path / "run"\n    _seed_ranked_hsic_run(run_dir)\n    runner = CliRunner()\n    result = runner.invoke(app, ["pirs", "export-hsic-report", "--run-dir", str(run_dir)])\n    assert result.exit_code == 0, result.output\n    assert "hsic_report_gate" in result.output or "evidence_count" in result.output\n    manifest = run_dir / "Tables" / "hsic_evidence_report_manifest.json"\n    inspect_result = runner.invoke(app, ["pirs", "inspect-hsic-report", "--manifest", str(manifest)])\n    assert inspect_result.exit_code == 0, inspect_result.output\n    assert "exported" in inspect_result.output\n'
AUDIT = '\nfrom __future__ import annotations\n\nimport json\nimport tempfile\nfrom pathlib import Path\n\nfrom pegasus.output.bundle import create_empty_output_bundle\nfrom pegasus.output.validate import validate_output_bundle\nfrom pegasus.workflows.hsic_report import inspect_hsic_report_manifest, run_export_hsic_report\n\n\ndef _write_json(path: Path, payload: dict) -> None:\n    path.parent.mkdir(parents=True, exist_ok=True)\n    path.write_text(json.dumps(payload, ensure_ascii=False, sort_keys=True, indent=2), encoding="utf-8")\n\n\ndef main() -> int:\n    errors: list[str] = []\n    with tempfile.TemporaryDirectory() as tmp:\n        run_dir = Path(tmp) / "run"\n        create_empty_output_bundle(run_dir)\n        tables = run_dir / "Tables"\n        card = {\n            "rank": 1,\n            "hypothesis_id": "hsic__resid__cov_a",\n            "residual_field_id": "resid",\n            "covariate_field_id": "cov_a",\n            "metrics": {"statistic": 1.1, "p_value": 0.02, "q_value": 0.05, "n_eff": 30.0},\n            "state": "exploratory",\n            "evidence_tier": "supported_descriptive",\n            "decision": "retain_for_review",\n            "warnings": [],\n            "dashboard_safe": True,\n            "read_only": True,\n        }\n        _write_json(tables / "dashboard_hsic_cards.json", {\n            "schema_version": "1.0",\n            "slice": "18B",\n            "read_only": True,\n            "cards": [card],\n        })\n        _write_json(tables / "hsic_residual_scan_ranking_manifest.json", {\n            "schema_version": "1.0",\n            "slice": "18B",\n            "status": "ranked",\n            "rank_count": 1,\n            "dashboard_card_count": 1,\n            "ranked_hypotheses": [card],\n        })\n        payload = run_export_hsic_report(run_dir=run_dir)\n        if payload.get("status") != "exported":\n            errors.append("report status was not exported")\n        if payload.get("evidence_count") != 1:\n            errors.append("report evidence count mismatch")\n        for name in ["hsic_evidence_report.json", "hsic_evidence_report.md", "hsic_evidence_report.csv", "hsic_evidence_report_manifest.json"]:\n            if not (tables / name).exists():\n                errors.append(f"missing report artifact: {name}")\n        md = (tables / "hsic_evidence_report.md").read_text(encoding="utf-8")\n        if "read-only descriptive export" not in md:\n            errors.append("markdown report did not declare read-only export")\n        inspect = inspect_hsic_report_manifest(tables / "hsic_evidence_report_manifest.json")\n        if inspect.get("read_only") is not True:\n            errors.append("inspect manifest did not preserve read_only true")\n        validation = validate_output_bundle(run_dir=str(run_dir))\n        if not validation.ok:\n            errors.extend(validation.errors)\n        run_config = json.loads((run_dir / "RunConfig.json").read_text(encoding="utf-8"))\n        if run_config.get("hsic_report_gate", {}).get("status") != "exported":\n            errors.append("run summary missing hsic_report_gate")\n    print(json.dumps({"ok": not errors, "errors": errors}, ensure_ascii=False, sort_keys=True, indent=2))\n    if errors:\n        return 1\n    print("AUDIT PASSED: Slice 18C HSIC report export")\n    return 0\n\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n'


def patch_cli() -> None:
    path = ROOT / "src" / "pegasus" / "cli.py"
    if not path.exists():
        raise SystemExit("Missing src/pegasus/cli.py")
    text = path.read_text(encoding="utf-8")
    if "pirs_app" not in text:
        raise SystemExit("src/pegasus/cli.py does not expose pirs_app; cannot attach Slice 18C commands safely")
    if "import json" not in text:
        text = "import json\n" + text
    if "from pathlib import Path" not in text:
        text = "from pathlib import Path\n" + text
    marker_start = "# BEGIN SLICE18C HSIC REPORT EXPORT CLI"
    marker_end = "# END SLICE18C HSIC REPORT EXPORT CLI"
    pattern = re.compile(rf"\n?{re.escape(marker_start)}.*?{re.escape(marker_end)}\n?", re.S)
    text = pattern.sub("\n", text)
    text = text.rstrip() + "\n\n" + CLI_BLOCK.strip() + "\n"
    path.write_text(text, encoding="utf-8")


def main() -> int:
    required = [
        ROOT / "src" / "pegasus" / "pirs" / "hsic_ranking.py",
        ROOT / "src" / "pegasus" / "workflows" / "hsic_rank.py",
        ROOT / "src" / "pegasus" / "dashboard" / "hsic_readonly.py",
    ]
    missing = [str(path) for path in required if not path.exists()]
    if missing:
        raise SystemExit("Missing Slice 18B prerequisite files: " + "; ".join(missing))
    write("src/pegasus/pirs/hsic_report.py", HSIC_REPORT)
    write("src/pegasus/workflows/hsic_report.py", HSIC_REPORT_WORKFLOW)
    write("tests/unit/test_slice18c_hsic_report_export.py", UNIT_TEST)
    write("tests/integration/test_slice18c_hsic_report_export_integration.py", INTEGRATION_TEST)
    write("scripts/dev/audits/audit_slice18c_hsic_report_export.py", AUDIT)
    patch_cli()
    print("Slice 18C updater applied: HSIC evidence report export and CLI added.")
    print("Touched files:")
    for rel in [
        "src/pegasus/pirs/hsic_report.py",
        "src/pegasus/workflows/hsic_report.py",
        "src/pegasus/cli.py",
        "tests/unit/test_slice18c_hsic_report_export.py",
        "tests/integration/test_slice18c_hsic_report_export_integration.py",
        "scripts/dev/audits/audit_slice18c_hsic_report_export.py",
    ]:
        print(f"  - {rel}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
